import type { int32 } from "@tsonic/core/types.js";

async function step(value: int32): Promise<int32> { return value + 1; }
export async function asyncChain(value: int32): Promise<int32> {
  const a = await step(value);
  const b = await step(a);
  return await step(b);
}

import type { int32 } from "@tsonic/core/types.js";

export function numberLoop(n: int32): number {
  let total = 0;
  for (let i: int32 = 0; i < n; i++) { total += i * 0.5; }
  return total;
}

import type { int32 } from "@tsonic/core/types.js";

export function intLoop(n: int32): int32 {
  let total: int32 = 0;
  for (let i: int32 = 0; i < n; i++) { total = total + (i & 7); }
  return total;
}

import type { int32 } from "@tsonic/core/types.js";

export function arrayPushSum(n: int32): int32 {
  const values: int32[] = [];
  for (let i: int32 = 0; i < n; i++) { values.push(i & 7); }
  let total: int32 = 0;
  for (const value of values) { total = total + value; }
  return total;
}

import type { int32 } from "@tsonic/core/types.js";

export function arrayIndexSum(n: int32): int32 {
  const values: int32[] = [];
  for (let i: int32 = 0; i < n; i++) { values.push(i & 7); }
  let total: int32 = 0;
  for (let i: int32 = 0; i < values.length; i++) { total = total + values[i]; }
  return total;
}

import type { int32 } from "@tsonic/core/types.js";

export function arrayPipeline(n: int32): int32 {
  const values: int32[] = [];
  for (let i: int32 = 0; i < n; i++) { values.push(i & 7); }
  return values.map((v) => v * 2).filter((v) => v > 4).reduce((a, v) => a + v, 0);
}

