  return out.length;
}

import type { int32 } from "@tsonic/core/types.js";

export function stringOps(path: string, n: int32): int32 {
  let hits: int32 = 0;
  for (let i: int32 = 0; i < n; i++) {
    if (path.startsWith("/api/") && path.split("/").length > 2) { hits = hits + 1; }
  }
  return hits;
}

import type { int32 } from "@tsonic/core/types.js";

export function stringTemplate(name: string, n: int32): int32 {
  let total: int32 = 0;
  for (let i: int32 = 0; i < n; i++) {
    const text = `user:${name}:${i}`;
    if (text.length > 5) { total = total + 1; }
