}

import type { int32 } from "@tsonic/core/types.js";

export function mapCount(n: int32): number {
  const counts = new Map<int32, int32>();
  for (let i: int32 = 0; i < n; i++) {
    const key: int32 = i & 63;
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return counts.size;
}

import type { int32 } from "@tsonic/core/types.js";

function apply(f: (value: int32) => int32, value: int32): int32 { return f(value); }
export function closureCall(n: int32): int32 {
  let total: int32 = 0;
  const k: int32 = 3;
  for (let i: int32 = 0; i < n; i++) { total = total + apply((v) => v + k, i); }
  return total;
}

import type { int32 } from "@tsonic/core/types.js";

function checked(value: int32): int32 {
  if (value < 0) { throw new Error("negative"); }
  return value * 2;
}
export function tryLoop(n: int32): int32 {
  let total: int32 = 0;
  for (let i: int32 = 0; i < n; i++) {
    try { total = total + checked(i); } catch { total = total - 1; }
  }
  return total;
}

