export function jsonStringify(name: string, n: int32): number {
  let total = 0;
  for (let i: int32 = 0; i < n; i++) {
    const text = JSON.stringify({ name: name, id: i });
    total = total + (text ?? "").length;
  }
  return total;
}

import type { int32 } from "@tsonic/core/types.js";

type Shape = { kind: "circle"; r: number } | { kind: "square"; s: number };
export function unionArea(n: int32): number {
  const shapes: Shape[] = [];
  for (let i: int32 = 0; i < n; i++) {
    shapes.push(i % 2 === 0 ? { kind: "circle", r: 1 } : { kind: "square", s: 2 });
  }
  let area = 0;
  for (const shape of shapes) {
    area += shape.kind === "circle" ? 3 * shape.r * shape.r : shape.s * shape.s;
  }
  return area;
}

