import type { int32 } from "@tsonic/core/types.js";
import { Dictionary } from "@tsonic/dotnet/System.Collections.Generic.js";
import { defaultof, out } from "@tsonic/csharp/lang.js";
export function csDictionary(n: int32): int32 {
  const counts = new Dictionary<int32, int32>();
  for (let i: int32 = 0; i < n; i++) {
    const key: int32 = i & 63;
    let current = defaultof<int32>();
    counts.TryGetValue(key, out(current));
    counts.Remove(key);
    counts.Add(key, current + 1);
  }
  return counts.Count;
}

